CREATE TABLE IF NOT EXISTS config (key TEXT PRIMARY KEY, value JSONB NOT NULL, updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS providers (id SERIAL PRIMARY KEY, name TEXT NOT NULL, display_name TEXT, api_key_enc TEXT NOT NULL, roles TEXT[] NOT NULL DEFAULT ARRAY['chat'], models TEXT[] DEFAULT ARRAY[]::TEXT[], embedding_models TEXT[] DEFAULT ARRAY[]::TEXT[], custom_endpoint TEXT, enabled BOOLEAN DEFAULT TRUE, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, created_at BIGINT NOT NULL, last_activity BIGINT NOT NULL, message_count INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS messages (id BIGSERIAL PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE CASCADE, role TEXT NOT NULL, text TEXT NOT NULL, ts BIGINT NOT NULL, provider TEXT, model TEXT, source TEXT);
CREATE TABLE IF NOT EXISTS memory (id BIGSERIAL PRIMARY KEY, timestamp TEXT NOT NULL, title TEXT, question TEXT NOT NULL, answer TEXT NOT NULL, variants TEXT[] DEFAULT ARRAY[]::TEXT[], keywords TEXT[] DEFAULT ARRAY[]::TEXT[], hit INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS unanswered_questions (id TEXT PRIMARY KEY, question TEXT NOT NULL, session_id TEXT, count INTEGER DEFAULT 1, first_asked TIMESTAMPTZ NOT NULL, last_asked TIMESTAMPTZ NOT NULL, resolved BOOLEAN DEFAULT FALSE, resolved_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS learning_queue (id TEXT PRIMARY KEY, question TEXT NOT NULL, original TEXT, variants TEXT[] DEFAULT ARRAY[]::TEXT[], count INTEGER DEFAULT 1, priority TEXT DEFAULT 'normal', first_asked TIMESTAMPTZ NOT NULL, last_asked TIMESTAMPTZ NOT NULL, resolved BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS feedback (id BIGSERIAL PRIMARY KEY, question TEXT NOT NULL, answer TEXT NOT NULL, rating TEXT NOT NULL, session_id TEXT, provider TEXT, model TEXT, source TEXT, timestamp TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS analytics_events (id BIGSERIAL PRIMARY KEY, event_type TEXT NOT NULL, session_id TEXT, ts BIGINT NOT NULL, date_key TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_chunks (id BIGSERIAL PRIMARY KEY, source TEXT NOT NULL, chunk_index INTEGER NOT NULL, text TEXT NOT NULL, keywords TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, type TEXT, title TEXT NOT NULL, message TEXT, level TEXT DEFAULT 'warning', timestamp TIMESTAMPTZ NOT NULL, read BOOLEAN DEFAULT FALSE);